import React, { createContext, useCallback, useContext, useEffect, useState } from 'react';

const AppContext = createContext(null);

export function AppProvider({ children }) {
  const [language, setLanguage] = useState('en');
  const [isDarkMode, setIsDarkMode] = useState(false);

  useEffect(() => {
    document.body.classList.toggle('dark-mode', isDarkMode);
  }, [isDarkMode]);

  const toggleLanguage = useCallback(() => setLanguage((p) => (p === 'en' ? 'ja' : 'en')), []);
  const toggleDarkMode = useCallback(() => setIsDarkMode((p) => !p), []);

  return (
    <AppContext.Provider value={{ language, isDarkMode, toggleLanguage, toggleDarkMode, setLanguage, setIsDarkMode }}>
      {children}
    </AppContext.Provider>
  );
}

export const useApp = () => {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error('useApp must be used inside AppProvider');
  return ctx;
};

export const useLanguage = () => {
  const { language } = useApp();
  return { language };
};

export const TranslatedText = ({ en, ja, as: Component = 'span', className = '', html, ...rest }) => {
  const { language } = useLanguage();
  const textContent = language === 'ja' ? ja || en : en;
  if (html) {
    return <Component className={className} dangerouslySetInnerHTML={{ __html: textContent }} {...rest} />;
  }
  return (
    <Component className={className} {...rest}>
      {textContent}
    </Component>
  );
};
