import React, { useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useApp, TranslatedText } from '../contexts/AppContext';

export function ProjectSection({ titleEn, titleJa, children, dense = false }) {
  return (
    <section style={{ marginTop: dense ? 'var(--space-lg)' : 'var(--space-xl)' }}>
      <h2
        style={{
          fontSize: 'var(--text-2xl)',
          fontWeight: 700,
          margin: '0 0 var(--space-md)',
          paddingBottom: 'var(--space-xs)',
          borderBottom: '1px solid var(--border-light)',
        }}
      >
        <TranslatedText en={titleEn} ja={titleJa} />
      </h2>
      <div>{children}</div>
    </section>
  );
}

export function ProjectChips({ items }) {
  return (
    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
      {items.map((t, i) => (
        <span
          key={i}
          className="tag"
          style={{
            padding: '3px 9px',
            fontSize: 'var(--text-xs)',
            background: 'var(--bg-tag)',
            color: 'var(--text-secondary)',
            borderRadius: 4,
            border: '1px solid var(--border-light)',
          }}
        >
          {t}
        </span>
      ))}
    </div>
  );
}

export default function ProjectPage({
  titleEn,
  titleJa,
  subtitleEn,
  subtitleJa,
  metaEn,
  metaJa,
  tech = [],
  sourceLinks = [],
  children,
}) {
  const { language, isDarkMode, toggleLanguage, toggleDarkMode } = useApp();

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  return (
    <>
      <header
        style={{
          position: 'sticky',
          top: 0,
          zIndex: 100,
          background: 'var(--bg-primary)',
          borderBottom: '1px solid var(--border-light)',
          padding: '12px 20px',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
        }}
      >
        <Link
          to="/"
          style={{
            color: 'var(--text-primary)',
            textDecoration: 'none',
            fontSize: 'var(--text-sm)',
            display: 'inline-flex',
            alignItems: 'center',
            gap: 6,
          }}
        >
          ← <TranslatedText en="Back to portfolio" ja="ポートフォリオに戻る" />
        </Link>
        <div style={{ display: 'flex', gap: 12 }}>
          <button
            type="button"
            onClick={toggleLanguage}
            style={{
              background: 'transparent',
              border: '1px solid var(--border-light)',
              color: 'var(--text-primary)',
              padding: '4px 10px',
              borderRadius: 4,
              fontSize: 'var(--text-xs)',
              cursor: 'pointer',
            }}
          >
            {language === 'en' ? '日本語' : 'EN'}
          </button>
          <button
            type="button"
            onClick={toggleDarkMode}
            aria-label="Toggle dark mode"
            style={{
              background: 'transparent',
              border: '1px solid var(--border-light)',
              color: 'var(--text-primary)',
              padding: '4px 10px',
              borderRadius: 4,
              fontSize: 'var(--text-xs)',
              cursor: 'pointer',
            }}
          >
            {isDarkMode ? '☀' : '☾'}
          </button>
        </div>
      </header>

      <main className="section" style={{ paddingTop: 'var(--space-xl)', paddingBottom: 'var(--space-2xl)' }}>
        <div className="container" style={{ maxWidth: 880 }}>
          {/* Hero */}
          <div style={{ marginBottom: 'var(--space-xl)' }}>
            <div
              style={{
                fontSize: 'var(--text-xs)',
                color: 'var(--text-muted)',
                textTransform: 'uppercase',
                letterSpacing: '1.5px',
                marginBottom: 'var(--space-sm)',
              }}
            >
              <TranslatedText en="Project" ja="プロジェクト" />
            </div>
            <h1 style={{ fontSize: 'var(--text-4xl)', fontWeight: 800, margin: '0 0 var(--space-sm)', lineHeight: 1.15 }}>
              <TranslatedText en={titleEn} ja={titleJa} />
            </h1>
            {(subtitleEn || subtitleJa) && (
              <p
                style={{
                  fontSize: 'var(--text-lg)',
                  color: 'var(--text-secondary)',
                  margin: '0 0 var(--space-md)',
                  lineHeight: 1.5,
                }}
              >
                <TranslatedText en={subtitleEn} ja={subtitleJa} />
              </p>
            )}
            {(metaEn || metaJa) && (
              <div style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)', marginBottom: 'var(--space-md)' }}>
                <TranslatedText en={metaEn} ja={metaJa} />
              </div>
            )}
            {tech.length > 0 && (
              <div style={{ marginBottom: 'var(--space-md)' }}>
                <ProjectChips items={tech} />
              </div>
            )}
            {sourceLinks.length > 0 && (
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, fontSize: 'var(--text-sm)' }}>
                {sourceLinks.map((l, i) => (
                  <a
                    key={i}
                    href={l.url}
                    target="_blank"
                    rel="noreferrer"
                    style={{
                      color: 'var(--text-primary)',
                      textDecoration: 'underline',
                      textDecorationColor: 'var(--border-light)',
                    }}
                  >
                    <TranslatedText en={l.labelEn} ja={l.labelJa} /> ↗
                  </a>
                ))}
              </div>
            )}
          </div>

          {children}

          <div style={{ marginTop: 'var(--space-2xl)', paddingTop: 'var(--space-lg)', borderTop: '1px solid var(--border-light)' }}>
            <Link to="/" style={{ color: 'var(--text-muted)', fontSize: 'var(--text-sm)', textDecoration: 'none' }}>
              ← <TranslatedText en="Back to portfolio" ja="ポートフォリオに戻る" />
            </Link>
          </div>
        </div>
      </main>
    </>
  );
}
