// Calculate duration from a start date to now
const calcDuration = (startDate) => {
  const start = new Date(startDate);
  const now = new Date();
  let months = (now.getFullYear() - start.getFullYear()) * 12 + (now.getMonth() - start.getMonth());
  if (now.getDate() >= start.getDate()) months += 1; // count partial month
  const yrs = Math.floor(months / 12);
  const mos = months % 12;
  const en = [yrs > 0 && `${yrs} yr${yrs > 1 ? 's' : ''}`, mos > 0 && `${mos} mo${mos > 1 ? 's' : ''}`].filter(Boolean).join(' ') || '1 mo';
  const ja = [yrs > 0 && `${yrs}年`, mos > 0 && `${mos}ヶ月`].filter(Boolean).join('') || '1ヶ月';
  return { en, ja };
};

